struct IupacSynthEditor::EdgesModel final:juce::ListBoxModel{IupacSynthEditor&e;explicit EdgesModel(IupacSynthEditor&x):e(x){}int getNumRows()override{return(int)e.owner_.snapshot().editedPatch.edges.size();}void paintListBoxItem(int i,juce::Graphics&g,int w,int h,bool s)override{auto p=e.owner_.snapshot().editedPatch;if(i<0||i>=(int)p.edges.size())return;if(s)g.fillAll(juce::Colour(0xff35506f));auto&r=p.edges[(std::size_t)i];g.setColour(juce::Colours::white);g.drawText(juce::String(r.source)+" -> "+r.destination+"  gain "+juce::String(r.gain,3),8,0,w-8,h,juce::Justification::centredLeft);}void selectedRowsChanged(int r)override{e.selectedEdge_=std::max(0,r);}};
struct IupacSynthEditor::MatrixModel final:juce::ListBoxModel{IupacSynthEditor&e;explicit MatrixModel(IupacSynthEditor&x):e(x){}int getNumRows()override{return(int)e.owner_.snapshot().editedPatch.matrix.size();}void paintListBoxItem(int i,juce::Graphics&g,int w,int h,bool s)override{auto p=e.owner_.snapshot().editedPatch;if(i<0||i>=(int)p.matrix.size())return;if(s)g.fillAll(juce::Colour(0xff35506f));auto&r=p.matrix[(std::size_t)i];g.setColour(r.enabled?juce::Colours::white:juce::Colours::grey);g.drawText(juce::String(r.id)+": "+sourceName((int)r.source)+" -> "+r.destinationNode+"."+r.destinationParameter+"  "+juce::String(r.depth,3),8,0,w-8,h,juce::Justification::centredLeft);}void selectedRowsChanged(int r)override{e.selectedRow_=std::max(0,r);auto p=e.owner_.snapshot().editedPatch;if(r<0||r>=(int)p.matrix.size())return;const auto&row=p.matrix[(std::size_t)r];e.matrixSource_.setSelectedItemIndex((int)row.source,juce::dontSendNotification);e.matrixDestination_.setText(juce::String(row.destinationNode)+"."+row.destinationParameter,juce::dontSendNotification);e.matrixDepth_.setValue(row.depth,juce::dontSendNotification);e.matrixEnabled_.setToggleState(row.enabled,juce::dontSendNotification);}};
