void IupacSynthEditor::showResult(const std::string&e,juce::String ok){status_.setText(e.empty()?ok:juce::String("Rejected: ")+e,juce::dontSendNotification);status_.setColour(juce::Label::textColourId,e.empty()?juce::Colours::lightgreen:juce::Colours::orange);}
std::filesystem::path IupacSynthEditor::presetDirectory()const{auto p=juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("IUPAC Synth 2").getChildFile("Presets");p.createDirectory();return p.getFullPathName().toStdString();}
juce::String IupacSynthEditor::sourceName(int i){constexpr std::array n{"E1","E2","E3","L1","L2","Velocity","Key tracking","Pitch bend","CC1","Macro 1","Macro 2","Macro 3","Macro 4"};return n[(std::size_t)juce::jlimit(0,12,i)];}
bool IupacSynthEditor::addModule(std::string_view type){auto*d=domain::findModule(type);if(!d){showResult("unknown module type",{});return false;}auto e=owner_.editPatch([&](auto&p){p.nodes.push_back(defaultNode(uniqueId(p,d->id),*d));});showResult(e,"Module added");refresh();return e.empty();}
bool IupacSynthEditor::removeSelectedModule(){auto row=selectedModule_;auto e=owner_.editPatch([row](auto&p){if(row<0||row>=(int)p.nodes.size())return;auto id=p.nodes[(std::size_t)row].id;std::erase_if(p.edges,[&](auto&x){return x.source==id||x.destination==id;});std::erase_if(p.matrix,[&](auto&x){return x.destinationNode==id;});p.nodes.erase(p.nodes.begin()+row);});showResult(e,"Module removed");refresh();return e.empty();}
bool IupacSynthEditor::addEdge(std::string a,std::string b,double g){auto e=owner_.editPatch([&](auto&p){p.edges.push_back({std::move(a),std::move(b),g});});showResult(e,"Edge added");refresh();return e.empty();}
bool IupacSynthEditor::removeSelectedEdge(){auto row=selectedEdge_;auto e=owner_.editPatch([row](auto&p){if(row>=0&&row<(int)p.edges.size())p.edges.erase(p.edges.begin()+row);});showResult(e,"Edge removed");refresh();return e.empty();}
bool IupacSynthEditor::addMatrixRow(){auto destination=matrixDestination_.getText().toStdString();auto dot=destination.find('.');if(dot==std::string::npos){showResult("add a modulatable module first",{});return false;}auto source=(domain::ModulationSource)std::max(0,matrixSource_.getSelectedItemIndex());auto e=owner_.editPatch([&](auto&p){p.matrix.push_back({uniqueRouteId(p),matrixEnabled_.getToggleState(),source,destination.substr(0,dot),destination.substr(dot+1),matrixDepth_.getValue()});});showResult(e,"Route added");refresh();return e.empty();}
bool IupacSynthEditor::updateSelectedMatrixRow(){auto destination=matrixDestination_.getText().toStdString();auto dot=destination.find('.');auto row=selectedRow_;if(dot==std::string::npos){showResult("select a matrix destination",{});return false;}auto e=owner_.editPatch([&](auto&p){if(row>=0&&row<(int)p.matrix.size()){auto&r=p.matrix[(std::size_t)row];r.source=(domain::ModulationSource)std::max(0,matrixSource_.getSelectedItemIndex());r.destinationNode=destination.substr(0,dot);r.destinationParameter=destination.substr(dot+1);r.depth=matrixDepth_.getValue();r.enabled=matrixEnabled_.getToggleState();}});showResult(e,"Route updated");refresh();return e.empty();}
bool IupacSynthEditor::setSelectedParameter(std::string_view id,std::size_t index,double v){auto row=selectedModule_;auto e=owner_.editPatch([&](auto&p){if(row<0||row>=(int)p.nodes.size())return;auto&node=p.nodes[(std::size_t)row];for(auto&x:node.parameters)if(x.id==id&&index<x.values.size())x.values[index]=v;if(node.type==domain::ModuleType::harmonic&&(id=="tilt"||id=="inharmonicity")){double tilt=0,inharmonicity=0;for(const auto&x:node.parameters){if(x.id=="tilt")tilt=x.values[0];else if(x.id=="inharmonicity")inharmonicity=x.values[0];}(void)domain::applyHarmonicSpectrum(node,tilt,inharmonicity);}});showResult(e,"Parameter updated");return e.empty();}
void IupacSynthEditor::refresh(){refreshModules();refreshDetail();refreshGraph();refreshMatrix();refreshPresets();}
void IupacSynthEditor::refreshModules(){auto p=owner_.snapshot().editedPatch;selectedModule_=juce::jlimit(0,std::max(0,(int)p.nodes.size()-1),selectedModule_);selectedEdge_=juce::jlimit(0,std::max(0,(int)p.edges.size()-1),selectedEdge_);moduleList_.updateContent();moduleList_.selectRow(selectedModule_,false,true);edgeList_.updateContent();edgeList_.selectRow(selectedEdge_,false,true);edgeSource_.clear();edgeDestination_.clear();int i=1;for(auto&n:p.nodes){edgeSource_.addItem(n.id,i);edgeDestination_.addItem(n.id,i++);}edgeDestination_.addItem("output",i);if(edgeSource_.getNumItems())edgeSource_.setSelectedItemIndex(0);edgeDestination_.setSelectedItemIndex(edgeDestination_.getNumItems()-1);}
void IupacSynthEditor::refreshDetail(){detailLabels_.clear();detailSliders_.clear();detailChoices_.clear();arrayEditors_.clear();auto p=owner_.snapshot().editedPatch;if(p.nodes.empty()){detailContent_.setSize(500,80);return;}selectedModule_=juce::jlimit(0,(int)p.nodes.size()-1,selectedModule_);auto&n=p.nodes[(std::size_t)selectedModule_];auto&d=domain::moduleCatalog()[(std::size_t)n.type];int y=8;for(std::size_t pi=0;pi<d.parameters.size();++pi){auto&pd=d.parameters[pi];auto*l=detailLabels_.add(new juce::Label);l->setText(pd.id.data(),juce::dontSendNotification);l->setBounds(8,y,175,28);detailContent_.addAndMakeVisible(l);if(pd.kind==domain::ParameterKind::discrete){auto*c=detailChoices_.add(new juce::ComboBox);for(std::size_t i=0;i<pd.choices.size();++i)c->addItem(pd.choices[i].data(),(int)i+1);c->setSelectedItemIndex((int)n.parameters[pi].values[0]);c->onChange=[this,id=std::string(pd.id),c]{setSelectedParameter(id,0,c->getSelectedItemIndex());};c->setBounds(190,y,280,28);detailContent_.addAndMakeVisible(c);}else if(pd.arraySize){auto*t=arrayEditors_.add(new juce::TextEditor);juce::String v;for(std::size_t i=0;i<n.parameters[pi].values.size();++i){if(i)v<<", ";v<<juce::String(n.parameters[pi].values[i],4);}t->setText(v,false);t->setName(juce::String(pd.id.data())+" array");t->onReturnKey=[this,id=std::string(pd.id),t,count=pd.arraySize]{std::stringstream ss(t->getText().toStdString());std::vector<double>v;std::string x;while(std::getline(ss,x,','))try{v.push_back(std::stod(x));}catch(...){v.clear();break;}auto row=selectedModule_;auto e=owner_.editPatch([&](auto&p){if(row>=0&&row<(int)p.nodes.size())for(auto&z:p.nodes[(std::size_t)row].parameters)if(z.id==id&&v.size()==count)z.values=v;});showResult(e,"Array updated");};t->setBounds(190,y,std::max(280,detailViewport_.getWidth()-210),28);detailContent_.addAndMakeVisible(t);}else{auto*s=detailSliders_.add(new juce::Slider);s->setRange(pd.minimum,pd.maximum,(pd.maximum-pd.minimum)/10000);s->setValue(n.parameters[pi].values[0],juce::dontSendNotification);s->setTextBoxStyle(juce::Slider::TextBoxLeft,false,90,24);s->onValueChange=[this,id=std::string(pd.id),s]{setSelectedParameter(id,0,s->getValue());};s->setBounds(190,y,std::max(280,detailViewport_.getWidth()-210),28);detailContent_.addAndMakeVisible(s);}y+=34;}detailContent_.setSize(std::max(500,detailViewport_.getWidth()-16),y+8);}
void IupacSynthEditor::refreshGraph(){auto p=owner_.snapshot().editedPatch;juce::String s="Validated audio flow\n";for(auto&e:p.edges)s<<e.source<<"  --"<<juce::String(e.gain,2)<<"-->  "<<e.destination<<"\n";if(p.edges.empty())s<<"(silent: no output connection)";graph_.setText(s,juce::dontSendNotification);}
void IupacSynthEditor::refreshMatrix(){auto p=owner_.snapshot().editedPatch;matrixList_.updateContent();matrixSource_.clear();for(int i=0;i<13;++i)matrixSource_.addItem(sourceName(i),i+1);matrixSource_.setSelectedId(1);matrixDestination_.clear();int id=1;for(auto&n:p.nodes)for(auto&pd:domain::moduleCatalog()[(std::size_t)n.type].parameters)if(pd.modulatable)matrixDestination_.addItem(juce::String(n.id)+"."+pd.id.data(),id++);if(id>1)matrixDestination_.setSelectedId(1);constexpr std::array names{"E1 attack","E1 decay","E1 sustain","E1 release","E2 attack","E2 decay","E2 sustain","E2 release","E3 attack","E3 decay","E3 sustain","E3 release","L1 rate","L2 rate"};for(std::size_t i=0;i<14;++i){auto&s=modulatorSliders_[i];s.setName(names[i]);double lo=0,hi=1,value=0;if(i<12){auto&e=p.envelopes[i/4];switch(i%4){case 0:lo=.001;hi=2;value=e.attack;break;case 1:lo=.01;hi=4;value=e.decay;break;case 2:value=e.sustain;break;default:lo=.02;hi=6;value=e.release;}}else{lo=.05;hi=12;value=p.lfos[i-12].rate;}s.setRange(lo,hi,(hi-lo)/10000);s.setValue(value,juce::dontSendNotification);s.onValueChange=[this,i,&s]{auto v=s.getValue();showResult(owner_.editPatch([=](auto&p){if(i<12){auto&e=p.envelopes[i/4];switch(i%4){case 0:e.attack=v;break;case 1:e.decay=v;break;case 2:e.sustain=v;break;default:e.release=v;}}else p.lfos[i-12].rate=v;}),"Modulator updated");};}for(std::size_t i=0;i<2;++i){auto&w=lfoWaveforms_[i];w.setName("L"+juce::String((int)i+1)+" waveform");w.setSelectedItemIndex((int)p.lfos[i].waveform,juce::dontSendNotification);w.onChange=[this,i,&w]{const auto value=w.getSelectedItemIndex();showResult(owner_.editPatch([i,value](auto&patch){patch.lfos[i].waveform=(domain::LfoWaveform)value;}),"LFO waveform updated");};}for(std::size_t i=0;i<4;++i){auto&t=macroEditors_[i];t.setName("Macro "+juce::String((int)i+1)+" label and default");t.setText(juce::String(p.macros[i].label)+" | "+juce::String(p.macros[i].defaultValue,3),false);t.onReturnKey=[this,i,&t]{auto text=t.getText();auto split=text.indexOfChar('|');auto label=text.substring(0,split).trim().toStdString();auto value=text.substring(split+1).getDoubleValue();showResult(owner_.editPatch([&](auto&p){p.macros[i]={label,value};}),"Macro updated");refreshModules();};}}
void IupacSynthEditor::refreshPresets(){auto previous=presetList_.getText();presets_=owner_.presetFiles(presetDirectory());presetList_.clear();int i=1;for(auto&p:presets_)presetList_.addItem(p.stem().string(),i++);presetList_.setText(previous,juce::dontSendNotification);presetList_.setTextWhenNothingSelected("Preset library");}
void IupacSynthEditor::timerCallback(){auto s=owner_.publicationStatus();meter_.setText("Output "+juce::String(juce::Decibels::gainToDecibels(owner_.outputPeak(),-100.f),1)+" dBFS   Voices "+juce::String((int)owner_.activeVoiceCount())+"   Generation "+juce::String((juce::int64)s.audible)+(s.transitioning?" (transitioning)":" (audible)"),juce::dontSendNotification);
#if IUPAC_ENABLE_CHEMISTRY
 auto chemistry=owner_.chemistryStatus();if(chemistry.generation!=shownChemistryGeneration_||(!chemistry.busy&&status_.getText().startsWith("Chemistry"))){shownChemistryGeneration_=chemistry.generation;status_.setText("Chemistry: "+juce::String(chemistry.text),juce::dontSendNotification);status_.setColour(juce::Label::textColourId,chemistry.busy?juce::Colours::yellow:juce::Colours::lightgreen);if(chemistry.trace.isNotEmpty())chemistryTrace_.setText(chemistry.trace,false);}
#endif
}
